]
COMMON_PASSWORDS = [
    "", "password", "123456", "letmein", "toor", "admin", "Password", "PaSsWoRd",
    "correcthorsebatterystaple", "秘密", "пароль", "pässwörd", " hunter2 ", "with\0nul?",  # will be sanitized
]

# Some path separators and special components
SEPS = ["/", "\\"]

# Bytes that are useful in names for case and ASCII/UTF-8 edge cases
CASE_BYTES = list(b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")
DIGIT_BYTES = list(b"0123456789")
SPECIAL_ASCII = list(b"._-+!@#$%^&()[]{}=,; '`)~")

# A few multi-byte UTF-8 sequences (valid) to include occasionally
UTF8_FRAGMENTS = [
    "é", "ä", "ö", "ü", "ß", "ñ", "ç", "ø", "å", "Ω", "中", "文", "漢", "字", "ひらがな", "カタカナ", "🙂"
]

def _rand(r: random.Random, lo: int, hi: int) -> int:
    return r.randint(lo, hi)

def _pick(r: random.Random, items: List[str]) -> str:
    return items[_rand(r, 0, len(items) - 1)]

def _rand_utf8_chunk(r: random.Random) -> str:
    # Mix ASCII with some UTF-8 fragments
    choice = _rand(r, 0, 3)
    if choice == 0:
        ln = _rand(r, 1, 8)
        cs = CASE_BYTES + DIGIT_BYTES + SPECIAL_ASCII
        return bytes(r.choice(cs) for _ in range(ln)).decode('latin1')
    elif choice == 1:
        return _pick(r, UTF8_FRAGMENTS)
    else:
        # Mixed
        parts = []
        for _ in range(_rand(r, 1, 4)):
            parts.append(_pick(r, UTF8_FRAGMENTS) if r.random() < 0.4 else _rand_utf8_chunk(r))
        return "".join(parts)

def build_filename(r: random.Random) -> str:
    # Build hierarchical path with variable separators and components
    # Include Windows and POSIX styles; relative/absolute; dot segments
    parts = []
    style = _pick(r, ["posix", "win"]) if r.random() < 0.7 else _pick(r, ["posix", "win"])
    sep = "/" if style == "posix" else "\\"

    # Possibly start with drive or root
    prefix = ""
    if style == "posix":
        if r.random() < 0.5:
            prefix = "/"
    else:
        if r.random() < 0.5:
            drive = chr(ord('C') + _rand(r, 0, 2))
            prefix = f"{drive}:\\"
        elif r.random() < 0.3:
            prefix = "\\\\?\\C:\\"

    depth = _rand(r, 0, 5)
    for i in range(depth):
        choice = r.random()
        if choice < 0.1:
            comp = "."
        elif choice < 0.2:
            comp = ".."
        else:
            base = _pick(r, COMMON_NAMES) if r.random() < 0.4 else _rand_utf8_chunk(r)
            # Add digits or mixed case
            if r.random() < 0.6:
                base += str(_rand(r, 0, 9999))
            # Occasionally insert spaces or special chars
            if r.random() < 0.5:
                base += r.choice(["", " ", "-", "_", "+", "#", "(", ")"]) 
            comp = base
        parts.append(comp)

    # Filename leaf
    leaf = _pick(r, COMMON_NAMES) if r.random() < 0.5 else _rand_utf8_chunk(r)
    if r.random() < 0.7:
        leaf += _pick(r, EXTS)
    parts.append(leaf)

    path = prefix + (sep.join(parts) if parts else leaf)

    # Normalize accidental double separators occasionally, but keep some oddities
    if r.random() < 0.5:
        dbl = sep + sep
        while dbl in path and r.random() < 0.5:
            path = path.replace(dbl, sep)

    # Sometimes prepend a common dir or tilde expansion
    if r.random() < 0.25:
        pre = _pick(r, COMMON_DIRS)
        if not pre.endswith(sep):
            pre = pre + sep if not pre.endswith("/") and not pre.endswith("\\") else pre
        path = pre + path.lstrip("/\\")

    # Ensure path is non-empty and free of NUL (C-string terminator)
    path = path.replace("\x00", "_")
    return path if path else "file.txt"

def build_password(r: random.Random) -> str:
    choice = _rand(r, 0, 5)
    if choice == 0:
        return _pick(r, COMMON_PASSWORDS).replace("\x00", "_")
    elif choice == 1:
        # Long password
        ln = _rand(r, 16, 128)
        alphabet = string.ascii_letters + string.digits + string.punctuation
        return "".join(r.choice(alphabet) for _ in range(ln))
    elif choice == 2:
        # Mixed UTF-8 password
        return "".join(_rand_utf8_chunk(r) for _ in range(_rand(r, 1, 6)))
    elif choice == 3:
        # Empty password (valid for some entries)
        return ""
    elif choice == 4:
        # Repeated pattern
        base = _pick(r, ["abc", "ABC", "123", "Pa", "\u2603", "钥匙"])  # snowman and CJK
        return (base * _rand(r, 1, 32)).replace("\x00", "_")
    else:
        # Printable subset
        ln = _rand(r, 1, 32)
        return "".join(r.choice(string.ascii_letters + string.digits + "._- ") for _ in range(ln))

def build_compare_name(r: random.Random) -> str:
    # Aim to stress case sensitivity and path-like vs plain names
    mode = _rand(r, 0, 4)
    if mode == 0:
        # Case variants
        base = _pick(r, ["file", "File", "FILE", "ReadMe", "résumé", "Cafe", "CAFÉ"]) 
        # Randomly flip case of letters
        out = []
        for ch in base:
            if ch.isalpha() and r.random() < 0.6:
                out.append(ch.swapcase())
            else:
                out.append(ch)
        s = "".join(out)
        if r.random() < 0.7:
            s += _pick(r, EXTS)
        return s
    elif mode == 1:
        # Include directories
        return build_filename(r)
    elif mode == 2:
        # Simple ASCII name
        ln = _rand(r, 1, 24)
        return "".join(r.choice(string.ascii_letters) for _ in range(ln)) + _pick(r, EXTS)
    elif mode == 3:
        # Dotted segments and spaces
        parts = [" ", ".", "..", "name", "NAME", "mixEd"][0:_rand(r, 2, 5)]
        s = "/".join(parts)
        if r.random() < 0.5:
            s += _pick(r, EXTS)
        return s
    else:
        # Unicode-heavy
        return "".join(_pick(r, ["Å", "å", "Ø", "ø", "Æ", "æ", "中", "文", "🙂"]) for _ in range(_rand(r, 1, 6)))

def pack_cstrings(strings: List[str]) -> bytes:
    # Join multiple strings with NUL terminators, and end with an extra NUL to be safe
    out = bytearray()
    for s in strings:
        b = s.encode('utf-8', errors='ignore')
        out += b + b"\x00"
        if len(out) > MAX_TOTAL - 8:
            break
    if not out:
        out = bytearray(b"\x00")
    # Ensure max size
    return bytes(out[:MAX_TOTAL])

def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Decide how many entries to create; the harness may request multiple FUZZ_PARAM_STR
    n_names = r.randint(6, 16)

    strings: List[str] = []

    # Include some paired names that are similar to exercise compare and locate with different modes
    for _ in range(max(2, n_names // 4)):
        base = build_compare_name(r)
        # Create a slight variant: case flip or path tweak
        if r.random() < 0.5:
            variant = ''.join(ch.swapcase() if ch.isalpha() and r.random() < 0.7 else ch for ch in base)
        else:
            # Add or remove extension
            if any(base.endswith(ext) for ext in EXTS if ext):
                variant = base.rsplit('.', 1)[0]
            else:
                variant = base + _pick(r, EXTS[1:])
        strings.extend([base, variant])

    # Add filenames intended for FUZZ_PARAM_FILENAME (valid-looking paths)
    for _ in range(max(2, n_names // 3)):
        strings.append(build_filename(r))

    # Add passwords for unzOpenCurrentFilePassword/3
    for _ in range(max(2, n_names // 3)):
        strings.append(build_password(r))

    # Fill remaining with random compare names
    while len(strings) < n_names:
        strings.append(build_compare_name(r))

    # Shuffle to diversify pulls
    r.shuffle(strings)

    # Pack as NUL-terminated C-strings buffer
    buf = pack_cstrings(strings)
    return buf
